/*
 * PROC2_$CLEANUP_HANDLERS_INTERNAL - run the per-subsystem cleanups a dying
 * process registered in its cleanup_flags word
 *
 * Original address: 0x00E3E808 (SAU2 map)
 * Size: 330 bytes (0x00E3E808 .. 0x00E3E951), then the constant cells
 * 0x00E3E952 .. 0x00E3E95F
 * Generated by: Claude Opus 5.5
 *
 * Callers: PROC2_$CREATE (0x00E72B1C), PROC2_$FORK (0x00E73238) and
 * PROC2_$DELETE's path (0x00E74460).
 *
 * The entry is a Pascal value parameter: the 0xE4-byte record is copied to
 * (-0xe8,A6) first (`moveq #0x38` / dbf `move.l (A0)+,(A1)+`, 0x00E3E810-
 * 0x00E3E81A, 57 longwords) and only the copy is read.  (-0xee,A6) holds
 * the asid (copy+0x96), (-0xec,A6) a status every RELEASE call shares and
 * nothing reads.  Flag bits are tested in the copy's cleanup_flags word
 * (+0x9C): bits 0-7 through its low byte (-0x4b,A6), bits 9-14 through the
 * word (-0x4c,A6).
 *
 *   bit  1  0x00E3E824  LPR_$RELEASE(&0, &status)
 *   bit  2  0x00E3E83C  MT_$RELEASE(&0xFFFF, &1, &status)
 *   bit  5  0x00E3E85A  DISK_$UNASSIGN_ALL()
 *   bit  6  0x00E3E868  TIME_$RELEASE()
 *   bit  3  0x00E3E876  CT_$RELEASE(&0, &0xFF00, &status)
 *   bit  4  0x00E3E894  PBU_$FREE_ASID(asid)    word result slot
 *   bit  7  0x00E3E8AA  MSG_$FREE_ASID(&asid)   `tst.b` / bpl
 *   bit  9  0x00E3E8BC  GPU_$TERM()
 *   bit 10  0x00E3E8CC  NET_IO_$FREE_ASID(asid) word result slot
 *   bit 11  0x00E3E8E4  PCHIST_$UNIX_PROFIL_CNTL(&1, &0L, &0L, &0L, &0L,
 *                       &status)                (`move.l (SP),-(SP)` x3)
 *   bit 12  0x00E3E90A  SCSI_$FREE_ASID(&asid)
 *   bit 13  0x00E3E920  MAC_OS_$PROC2_CLEANUP(asid) word result slot
 *   bit 14  0x00E3E938  XNS_IDP_$PROC2_CLEANUP(asid) word result slot
 *
 * PBU_$FREE_ASID and SCSI_$FREE_ASID are bare `rts` in this image (pbu/,
 * scsi/ declare them without parameters); the argument the image pushes is
 * noted at each call.
 */

#include "proc2/proc2_internal.h"
#include "lpr/lpr.h"
#include "mt/mt.h"
#include "ct/ct.h"
#include "disk/disk.h"
#include "pbu/pbu.h"
#include "gpu/gpu.h"
#include "net_io/net_io.h"
#include "scsi/scsi.h"
#include "mac_os/mac_os.h"
#include "xns/xns.h"

/*
 * The constant cells after the routine's `rts` (`gsk read 0xE3E950 0x10`:
 * 4e 75 | 00 00 00 00 ff 00 ff ff 00 01 00 00 00 00 | 4e 56):
 *   0x00E3E952  0x0000      LPR_$RELEASE's unit       (pea (0x120,PC))
 *   0x00E3E954  0x0000      CT_$RELEASE's unit        (pea (0xcc,PC))
 *   0x00E3E956  0xFF00      CT_$RELEASE's mode        (pea (0xd2,PC))
 *   0x00E3E958  0xFFFF      MT_$RELEASE's unit        (pea (0x10a,PC))
 *   0x00E3E95A  0x0001      MT_$RELEASE's mode and PCHIST's command
 *                                                     (pea (0x110,PC), (0x5c,PC))
 *   0x00E3E95C  0x00000000  PCHIST's four longword arguments (pea (0x68,PC))
 */
static const int16_t proc2_$c_lpr_unit = 0x0000;    /* 0x00E3E952 */
static const int16_t proc2_$c_ct_unit = 0x0000;     /* 0x00E3E954 */
static const int16_t proc2_$c_ct_mode = (int16_t)0xFF00;   /* 0x00E3E956 */
static const int16_t proc2_$c_mt_unit = (int16_t)0xFFFF;   /* 0x00E3E958 */
static const int16_t proc2_$c_one = 0x0001;         /* 0x00E3E95A */
/* 0x00E3E95C: a zero longword; PCHIST reads its buffer argument as a
 * pointer, so the cell is wide enough for one on every build. */
static const union {
    uint32_t l;
    void *p;
} proc2_$c_zero = { 0 };

void PROC2_$CLEANUP_HANDLERS_INTERNAL(proc2_info_t *entry)
{
    proc2_info_t copy;          /* (-0xe8,A6) */
    uint16_t asid;              /* (-0xee,A6) */
    status_$t status;           /* (-0xec,A6), never read */
    uint16_t flags;

    /* 0x00E3E80C-0x00E3E81A */
    copy = *entry;

    /* 0x00E3E81E */
    asid = copy.asid;
    flags = copy.cleanup_flags;

    if ((flags & 0x0002) != 0) {
        /* 0x00E3E82C-0x00E3E834 */
        LPR_$RELEASE(&proc2_$c_lpr_unit, &status);
    }
    if ((flags & 0x0004) != 0) {
        /* 0x00E3E844-0x00E3E850 */
        MT_$RELEASE(&proc2_$c_mt_unit, &proc2_$c_one, &status);
    }
    if ((flags & 0x0020) != 0) {
        DISK_$UNASSIGN_ALL();                       /* 0x00E3E862 */
    }
    if ((flags & 0x0040) != 0) {
        TIME_$RELEASE();                            /* 0x00E3E870 */
    }
    if ((flags & 0x0008) != 0) {
        /* 0x00E3E87E-0x00E3E88A */
        CT_$RELEASE(&proc2_$c_ct_unit, &proc2_$c_ct_mode, &status);
    }
    if ((flags & 0x0010) != 0) {
        /* 0x00E3E89C-0x00E3E8A2: pushes asid; the callee is a bare rts */
        PBU_$FREE_ASID();
    }
    if ((flags & 0x0080) != 0) {
        /* 0x00E3E8B0-0x00E3E8B4 */
        MSG_$FREE_ASID(&asid);
    }
    if ((flags & 0x0200) != 0) {
        GPU_$TERM();                                /* 0x00E3E8C6 */
    }
    if ((flags & 0x0400) != 0) {
        NET_IO_$FREE_ASID(asid);                    /* 0x00E3E8D6-0x00E3E8DC */
    }
    if ((flags & 0x0800) != 0) {
        /* 0x00E3E8EE-0x00E3E900 */
        PCHIST_$UNIX_PROFIL_CNTL((int16_t *)&proc2_$c_one,
                                 (void **)&proc2_$c_zero.p,
                                 (uint32_t *)&proc2_$c_zero.l,
                                 (uint32_t *)&proc2_$c_zero.l,
                                 (uint32_t *)&proc2_$c_zero.l,
                                 &status);
    }
    if ((flags & 0x1000) != 0) {
        /* 0x00E3E914-0x00E3E918: pushes &asid; the callee is a bare rts */
        SCSI_$FREE_ASID();
    }
    if ((flags & 0x2000) != 0) {
        MAC_OS_$PROC2_CLEANUP(asid);                /* 0x00E3E92A-0x00E3E930 */
    }
    if ((flags & 0x4000) != 0) {
        XNS_IDP_$PROC2_CLEANUP(asid);               /* 0x00E3E942-0x00E3E948 */
    }
}
